<script setup>
import { ref,watch } from 'vue'; import { useRoute, RouterLink } from 'vue-router'; import { api } from '../lib/api'; import { num,pct,date,money,obraPath } from '../lib/format'; import StatTile from '../components/StatTile.vue';import DataChart from '../components/DataChart.vue';import PageCard from '../components/PageCard.vue';
const route=useRoute(),data=ref(null),error=ref(''),loading=ref(false),selected=ref(0);
async function load(){loading.value=true;error.value='';try{data.value=await api.get(`/obras/${route.params.obraId}/resumen`)}catch(e){error.value=e.message}finally{loading.value=false}}
watch(()=>route.params.obraId,load,{immediate:true});
</script>
<template><p v-if="error" class="notice bad">{{error}}</p><p v-else-if="loading">Cargando obra…</p><template v-else-if="data"><div class="grid-aside obra-overview"><PageCard title="Curva S" description="Programado, real y reprogramado" focal><div class="pills curve-tabs"><button v-for="(c,i) in data.overview?.curve_tabs" :key="c.id" class="pill" :aria-selected="selected===i" @click="selected=i">{{c.name}}</button></div><DataChart v-if="data.overview?.curve_tabs?.[selected]" :data="data.overview.curve_tabs[selected].chart"/><p v-else>Sin curvas registradas.</p></PageCard><div class="obra-overview__side"><StatTile label="Desvío frente al programa" :value="data.overview?.delay" :hint="data.overview?.delay_hint" :tone="data.overview?.delay_tone"/><StatTile label="Cumplimiento en prevención" :value="data.overview?.pdr_text" :hint="data.overview?.pdr_hint"/><StatTile label="Facturado del contrato" :value="pct(data.summary?.payments?.pct)" :hint="data.overview?.billing_hint"/></div></div>
<div class="stat-grid cols-4"><StatTile label="Personas en obra" :value="num(data.summary?.total_people)" :hint="data.overview?.people_hint"/><StatTile label="Consultas sin responder" :value="num(data.summary?.pending)" :tone="data.summary?.pending?'warn':'ok'"/><StatTile label="Accidentes acumulados" :value="num(data.overview?.accidents)"/><StatTile label="Último informe" :value="date(data.summary?.latest_report?.fecha_corte)"/></div>
<div class="grid-aside"><PageCard title="Dotación y horas por semana" description="Personal Tocal y subcontratos"><DataChart type="staff" :data="data.overview?.staffing_chart" :height="330"/></PageCard><PageCard title="Requiere atención"><ul v-if="data.overview?.alerts?.length" class="alert-list"><li v-for="(a,i) in data.overview.alerts" :key="i" class="alert-item"><div><strong>{{a.title}}</strong><p>{{a.text}}</p></div></li></ul><p v-else>Todo en orden. No hay alertas.</p></PageCard></div>
<PageCard title="Datos del contrato"><div class="facts-columns"><dl class="facts"><div v-for="(v,k) in data.obra" :key="k" v-show="!['id','created_at'].includes(k)"><dt>{{k.replaceAll('_',' ')}}</dt><dd>{{v===null?'—':typeof v==='boolean'?(v?'Sí':'No'):v}}</dd></div></dl></div></PageCard></template></template>
